#include <iostream>
#include <sstream>
#include <string>
#include <algorithm>

struct AccountRecord {
    int accountNumber{0};
    char name[16]{""};
    double balance{0.0};

    void setName(const std::string& str) {
        std::size_t len = std::min(str.size(), sizeof(name) - 1);
        str.copy(name, len);
        name[len] = '\0';
    }
};

int main() {
    // Simulate binary stream storage in memory for portable execution
    std::stringstream binaryStorage(std::ios::in | std::ios::out | std::ios::binary);

    AccountRecord blankRecord;
    const int totalRecords = 5;

    // Initialize preallocated blank records
    for (int i = 0; i < totalRecords; ++i) {
        binaryStorage.write(reinterpret_cast<const char*>(&blankRecord), sizeof(AccountRecord));
    }

    // Verify allocated byte size
    binaryStorage.seekp(0, std::ios::end);
    std::streampos totalBytes = binaryStorage.tellp();

    std::cout << "Initialized records: " << totalRecords << "\n";
    std::cout << "Record size: " << sizeof(AccountRecord) << " bytes\n";
    std::cout << "Total allocated file size: " << totalBytes << " bytes\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <algorithm>

struct ClientRecord {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};

    void setNames(const std::string& last, const std::string& first) {
        std::size_t lenLast = std::min(last.size(), sizeof(lastName) - 1);
        last.copy(lastName, lenLast);
        lastName[lenLast] = '\0';

        std::size_t lenFirst = std::min(first.size(), sizeof(firstName) - 1);
        first.copy(firstName, lenFirst);
        firstName[lenFirst] = '\0';
    }
};

int main() {
    // In-memory binary fstream simulation with 10 blank slots (1-indexed: 1..10)
    std::stringstream file(std::ios::in | std::ios::out | std::ios::binary);
    ClientRecord blank;
    for (int i = 0; i < 10; ++i) {
        file.write(reinterpret_cast<const char*>(&blank), sizeof(ClientRecord));
    }

    // Write account 3 randomly
    ClientRecord client1{3, "", "", 125.50};
    client1.setNames("Smith", "John");
    file.seekp((client1.accountNumber - 1) * sizeof(ClientRecord));
    file.write(reinterpret_cast<const char*>(&client1), sizeof(ClientRecord));

    // Write account 7 randomly
    ClientRecord client2{7, "", "", -45.00};
    client2.setNames("Doe", "Jane");
    file.seekp((client2.accountNumber - 1) * sizeof(ClientRecord));
    file.write(reinterpret_cast<const char*>(&client2), sizeof(ClientRecord));

    // Read back account 3 directly without reading accounts 1 or 2
    ClientRecord readRecord;
    file.seekg((3 - 1) * sizeof(ClientRecord));
    file.read(reinterpret_cast<char*>(&readRecord), sizeof(ClientRecord));

    std::cout << "Account: " << readRecord.accountNumber << "\n"
              << "Name: " << readRecord.firstName << " " << readRecord.lastName << "\n"
              << "Balance: " << readRecord.balance << "\n";

    return 0;
}
